import{_ as a,o as e,c as r,a5 as l}from"./chunks/framework.BF53ZjCA.js";const c=JSON.parse('{"title":"光学测试","description":"","frontmatter":{"title":"光学测试","identification":"optical-tests"},"headers":[],"relativePath":"zh/identification/optical-tests.md","filePath":"zh/identification/optical-tests.md","lastUpdated":1790876393000}'),s={name:"zh/identification/optical-tests.md"};function n(i,t,o,p,d,h){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="光学测试" tabindex="-1">光学测试 <a class="header-anchor" href="#光学测试" aria-label="Permalink to &quot;光学测试&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>双折射（偏光镜）、多色性（二色镜）、紫外荧光（紫外灯）提供宝石的 光学与材料线索，可用于快速筛分品种并提示进一步检测方向。</p><aside class="gem-identification-boundary" aria-labelledby="identification-boundary-optical-tests-zh"><p class="gem-identification-boundary__eyebrow">IDENTIFICATION BOUNDARY</p><h2 id="identification-boundary-optical-tests-zh">边界与安全</h2><p>光学现象是证据链中的线索，不是“看见现象就能命名”的捷径。偏光镜、二色镜、紫外灯和光谱仪都需要合适的样品方向、光源/仪器条件与安全操作；荧光和吸收带不能单独证明天然、合成、处理或产地。 </p></aside><h2 id="鉴定步骤" tabindex="-1">鉴定步骤 <a class="header-anchor" href="#鉴定步骤" aria-label="Permalink to &quot;鉴定步骤&quot;">​</a></h2><p><strong>统一教学协议</strong></p><p>每项光学测试都按同一顺序阅读：目的 → 适用条件 → 操作与记录 → 结果解释 → 异常处理 → 风险/送检。光学反应受样品方向、切磨、光源、透明度和仪器影响，必须保留观察上下文。</p><table tabindex="0"><thead><tr><th>测试</th><th>主要输出</th><th>典型限制</th></tr></thead><tbody><tr><td>偏光镜</td><td>光性、消光与异常反应</td><td>方向、集合体、多晶结构和透明度</td></tr><tr><td>二色镜</td><td>颜色变化、方向和强度</td><td>光源、切磨方向与观察方向</td></tr><tr><td>紫外荧光</td><td>LW/SW、颜色和强度</td><td>灯具、距离、背景与样品重叠</td></tr><tr><td>光谱</td><td>吸收模式、仪器与读数质量</td><td>校准、光路、方向和解释经验</td></tr></tbody></table><h3 id="_1-偏光镜-先确认光性-再记录反应" tabindex="-1">1. 偏光镜：先确认光性，再记录反应 <a class="header-anchor" href="#_1-偏光镜-先确认光性-再记录反应" aria-label="Permalink to &quot;1. 偏光镜：先确认光性，再记录反应&quot;">​</a></h3><p><strong>目的：</strong> 观察样品在偏振条件下的光学反应，为候选分组提供线索。</p><p><strong>适用条件：</strong> 按仪器说明放置样品，确认样品透明度、形状和内部结构适合观察；集合体、多晶结构或应力可能造成复杂反应，应提前标记。</p><p><strong>操作与记录：</strong> 记录观察方向、旋转样品时的明暗变化、消光是否整体或局部、是否出现异常反应以及仪器设置。不要只写“有双折射”，要保留观察条件。</p><p><strong>结果解释：</strong> 双折射、消光和异常反应要结合切磨方向、透明度和其他物性解释；数值高不自动等于更容易识别，也不能单独命名。</p><p><strong>异常处理：</strong> 反应不稳定、样品内部复杂或无法判断是样品反应还是仪器误差时，记录不确定性并改用其他证据，不强行归类。</p><p><strong>风险/送检：</strong> 不为获取光学反应强行挤压或改变样品；结果冲突或涉及正式鉴定时保留记录并送检。</p><h3 id="_2-二色镜-记录方向与颜色变化" tabindex="-1">2. 二色镜：记录方向与颜色变化 <a class="header-anchor" href="#_2-二色镜-记录方向与颜色变化" aria-label="Permalink to &quot;2. 二色镜：记录方向与颜色变化&quot;">​</a></h3><p><strong>目的：</strong> 观察多色性及其方向性，为候选筛分提供补充线索。</p><p><strong>适用条件：</strong> 使用稳定光源，从不同方向观察；注明样品是刻面、弧面、透明还是半透明，因为切磨与透光路径会改变观察。</p><p><strong>操作与记录：</strong> 分别记录看到的颜色、强弱、观察方向和光源，不把“颜色不同”与“宝石名称”写在同一栏。</p><p><strong>结果解释：</strong> 多色性受晶体方向、切磨和光源影响；“没有明显变化”只是当前条件下的观察结果，不能直接排除某个品种。</p><p><strong>异常处理：</strong> 颜色变化很弱、视野不稳定或光源不一致时，标记观察质量不足，不用主观色名替代记录。</p><p><strong>风险/送检：</strong> 二色镜通常用于低风险观察，但仍应避免对镶嵌或易损样品施加不必要的操作；需要正式披露时升级送检。</p><h3 id="_3-紫外荧光-记录波段和条件" tabindex="-1">3. 紫外荧光：记录波段和条件 <a class="header-anchor" href="#_3-紫外荧光-记录波段和条件" aria-label="Permalink to &quot;3. 紫外荧光：记录波段和条件&quot;">​</a></h3><p><strong>目的：</strong> 记录样品在不同紫外波段下的反应，为下一步检测提供筛分线索。</p><p><strong>适用条件：</strong> 区分 LW/SW 条件，记录灯具、观察距离、环境背景和样品状态；确认设备符合安全要求。</p><p><strong>操作与记录：</strong> 记录反应颜色、强度、均匀性和观察条件；把“未观察到”与“设备未能稳定观察”区分开。</p><p><strong>结果解释：</strong> 荧光可帮助决定下一步检测，但天然、合成和处理样品之间可能重叠，不能单独作身份、处理或产地结论。</p><p><strong>异常处理：</strong> 环境光过强、样品位置变化、灯具状态不明或反应难以重复时，标记结果质量，不凭印象补写。</p><p><strong>风险/送检：</strong> 遵守紫外灯的眼睛与皮肤防护要求，不直视光源；高价值、异常或需要正式披露的样品交由专业人员处理。</p><h3 id="_4-光谱-把吸收带当作模式证据" tabindex="-1">4. 光谱：把吸收带当作模式证据 <a class="header-anchor" href="#_4-光谱-把吸收带当作模式证据" aria-label="Permalink to &quot;4. 光谱：把吸收带当作模式证据&quot;">​</a></h3><p><strong>目的：</strong> 记录吸收模式，为材料结构、致色因素和生长/处理线索提供补充证据。</p><p><strong>适用条件：</strong> 记录光源、仪器、校准/检查状态、样品方向和光路；样品厚度、透明度和表面状态会影响读数质量。</p><p><strong>操作与记录：</strong> 记录可见吸收带、谱形、读数质量和重复结果；无法稳定读谱时写“未获得可靠光谱”，不要凭记忆补全。</p><p><strong>结果解释：</strong> 吸收模式要与 RI、SG、包裹体、处理线索和样品限制交叉解释。它不是独立的产地指纹，也不能由单一谱带推出天然/合成结论。</p><p><strong>异常处理：</strong> 基线漂移、噪声、光路不稳定或不同方向结果冲突时，保留原始状态并标记待复核，不挑选最符合预期的谱图。</p><p><strong>风险/送检：</strong> 光谱仪的校准、光源和软件输出应按设备规范管理；涉及产地、天然/合成或处理意见时必须升级到专业实验室。</p><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>双折射与偏光反应需要结合各向异性、观察方向、切磨和透明度解释；不能按数值高低直接判断难易。</li><li>多色性必须注明光源、观察方向和颜色变化强度；二色镜结果只是候选支持或排除线索。</li><li>紫外荧光可用于筛分和选择下一步测试，但天然、合成和处理样品可能出现重叠反应。</li><li>光谱中的吸收带是需要校准、记录并交叉验证的模式证据，不是独立的产地指纹。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>数值</th><th>备注</th></tr></thead><tbody><tr><td>锆石</td><td>双折射示例：DR 0.059</td><td>仅作光学现象示例，需结合方向与其他证据</td></tr><tr><td>堇青石</td><td>强多色性</td><td>需记录光源与观察方向</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">参考依据与证据边界</h2><p class="gem-reference-block__intro">本页内容用于学习与检索；来源用于说明知识依据，不代表仅凭本页即可完成具体样品鉴定。</p><ul><li><a href="https://www.gia.edu/gems-gemology/winter-2024-gemstone-analysis" target="_blank" rel="noreferrer">GIA：宝石实验室分析流程</a><span>标准宝石学测试、实验室工作流与实验室培育钻石分析示例</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/winter-2019-analytical-methods-geographic-origin-determination-gemstones" target="_blank" rel="noreferrer">GIA：宝石产地分析方法综述</a><span>RI/SG 作为鉴定起点，以及产地判断所需的后续分析</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/winter-2024-infrared-spectroscopy" target="_blank" rel="noreferrer">GIA：红外光谱在宝石学中的应用</a><span>光谱与原子结构、天然/合成/处理线索之间的关系</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/ruby" target="_blank" rel="noreferrer">GIA 宝石百科：红宝石</a><span>红宝石的典型 RI、双折射、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/sapphire" target="_blank" rel="noreferrer">GIA 宝石百科：蓝宝石</a><span>蓝宝石的典型 RI、双折射、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/emerald" target="_blank" rel="noreferrer">GIA 宝石百科：祖母绿</a><span>祖母绿的典型 RI、双折射、比重、硬度与处理/合成/仿品边界</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/spinel" target="_blank" rel="noreferrer">GIA 宝石百科：尖晶石</a><span>尖晶石的典型 RI、均质性、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/diamond" target="_blank" rel="noreferrer">GIA 宝石百科：钻石</a><span>钻石的典型 RI、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/zircon" target="_blank" rel="noreferrer">GIA 宝石百科：锆石</a><span>锆石的典型 RI、双折射、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/articles/iolite-description" target="_blank" rel="noreferrer">GIA：堇青石（Iolite）描述</a><span>堇青石的强多色性与观察方向提示</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/tanzanite-description" target="_blank" rel="noreferrer">GIA：坦桑石描述</a><span>坦桑石的多色性、切磨方向、光源与热处理背景</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/peridot" target="_blank" rel="noreferrer">GIA 宝石百科：橄榄石</a><span>橄榄石典型 RI、双折射、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://my.gia.edu/FAQ/gia-faq-two-green-garnet" target="_blank" rel="noreferrer">GIA FAQ：沙弗莱石与翠榴石的区别</a><span>绿色石榴石颜色重叠与矿物差异提示</span><small>打开来源 ↗</small></li></ul></aside><p><em>详见<a href="./intro.html">鉴定总览</a>。</em></p>',42)])])}const m=a(s,[["render",n]]);export{c as __pageData,m as default};
